// Convierte la lectura única de la hoja (batchGet) en tablas con número de fila y encabezados
const hojas = ["Log Bot", "Cuentas", "Categorías", "Movimientos", "Cuotas tarjeta", "Por confirmar", "Documentos", "Préstamos", "Cuotas préstamo", "Personas", "Recurrentes", "Parámetros", "Activos", "Operaciones inversión", "Reventas", "Extractos", "Comercios", "Presupuestos", "Metas", "Historial"];
const vr = ($input.first().json.valueRanges || []);
const out = { _h: {} };
hojas.forEach((h, i) => {
  const v = (vr[i] && vr[i].values) || [];
  const head = (v[0] || []).map(x => String(x).trim());
  out._h[h] = head;
  out[h] = v.slice(1).map((fila, k) => {
    const o = { row_number: k + 2 };
    head.forEach((c, j) => { if (c) o[c] = fila[j] !== undefined ? fila[j] : ''; });
    return o;
  }).filter(o => Object.keys(o).some(c => c !== 'row_number' && o[c] !== '' && o[c] !== null));
});
return [{ json: out }];

const tz = 'America/Bogota';
const ahora = DateTime.now().setZone(tz);
const sello = ahora.toFormat('yyMMddHHmmss') + '-' + $execution.id;   // único aunque lleguen varias fotos en el mismo segundo
// Montos: acepta 25000, "25.000", "$ 25.000,50", "(3.797.362)"
const num = v => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').trim();
  if (!s || s === '-') return 0;
  const neg = /^\(.*\)$/.test(s) || s.startsWith('-');
  s = s.replace(/[^\d,.]/g, '');
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  else if ((s.match(/\./g) || []).length > 1 || /\.\d{3}$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : (neg ? -n : n);
};
// Fechas: acepta 2026-09-29, 29/09/2026, con hora, o número de serie de Sheets
const fecha = v => {
  if (typeof v === 'number') return DateTime.fromISO('1899-12-30', { zone: tz }).plus({ days: Math.floor(v) });
  const s = String(v || '').trim();
  for (const f of ['yyyy-MM-dd', 'd/M/yyyy', 'd/M/yy', 'yyyy-MM-dd H:mm', 'yyyy-MM-dd H:mm:ss', 'd/M/yyyy H:mm', 'd/M/yyyy H:mm:ss']) {
    const d = DateTime.fromFormat(s, f, { zone: tz });
    if (d.isValid) return d;
  }
  return DateTime.fromISO(s, { zone: tz });
};
const pesos = n => (n < 0 ? '-$' : '$') + String(Math.abs(Math.round(n))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

// Arma las consultas de precios: CoinGecko (cripto + dólar) y Stooq (ETF y acciones)
const T = $('Tablas').first().json;
const MAPA = { BTC: 'bitcoin', ETH: 'ethereum', LINK: 'chainlink', AVAX: 'avalanche-2', SOL: 'solana', ADA: 'cardano', XRP: 'ripple', DOT: 'polkadot', MATIC: 'matic-network', POL: 'polygon-ecosystem-token', DOGE: 'dogecoin', USDT: 'tether', USDC: 'usd-coin', BNB: 'binancecoin', LTC: 'litecoin' };
const activos = (T['Activos'] || []).filter(a => a.Activo && String(a['Activo vigente'] || 'Sí') !== 'No');
const cg = {}, bolsa = [];
for (const a of activos) {
  const s = String(a.Activo).toUpperCase(), nota = String(a.Notas || '').match(/coingecko:([\w-]+)/);
  if (['ETF', 'Acción'].includes(a['Tipo activo'])) { const sim = String(a['Símbolo GOOGLEFINANCE'] || s).split(':').pop().toLowerCase(); bolsa.push({ activo: s, url: `https://stooq.com/q/l/?s=${sim}.us&f=sd2t2c&h&e=csv` }); }
  else if (nota || MAPA[s]) cg[s] = nota ? nota[1] : MAPA[s];
}
const ids = [...new Set(['bitcoin', ...Object.values(cg)])];
return [{ json: { fuente: 'fx', url: 'https://open.er-api.com/v6/latest/USD' } }, { json: { fuente: 'coingecko', mapa: cg, url: `https://api.coingecko.com/api/v3/simple/price?ids=${ids.join(',')}&vs_currencies=usd,cop` } }, ...bolsa.map(b => ({ json: { fuente: 'stooq', ...b } }))];

const tz = 'America/Bogota';
const ahora = DateTime.now().setZone(tz);
const sello = ahora.toFormat('yyMMddHHmmss') + '-' + $execution.id;   // único aunque lleguen varias fotos en el mismo segundo
// Montos: acepta 25000, "25.000", "$ 25.000,50", "(3.797.362)"
const num = v => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').trim();
  if (!s || s === '-') return 0;
  const neg = /^\(.*\)$/.test(s) || s.startsWith('-');
  s = s.replace(/[^\d,.]/g, '');
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  else if ((s.match(/\./g) || []).length > 1 || /\.\d{3}$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : (neg ? -n : n);
};
// Fechas: acepta 2026-09-29, 29/09/2026, con hora, o número de serie de Sheets
const fecha = v => {
  if (typeof v === 'number') return DateTime.fromISO('1899-12-30', { zone: tz }).plus({ days: Math.floor(v) });
  const s = String(v || '').trim();
  for (const f of ['yyyy-MM-dd', 'd/M/yyyy', 'd/M/yy', 'yyyy-MM-dd H:mm', 'yyyy-MM-dd H:mm:ss', 'd/M/yyyy H:mm', 'd/M/yyyy H:mm:ss']) {
    const d = DateTime.fromFormat(s, f, { zone: tz });
    if (d.isValid) return d;
  }
  return DateTime.fromISO(s, { zone: tz });
};
const pesos = n => (n < 0 ? '-$' : '$') + String(Math.abs(Math.round(n))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

// Actualiza precios en Activos, el dólar en Parámetros y (una sola vez) el costo de los saldos iniciales
const T = $('Tablas').first().json;
const pedidos = $('Pedidos de precios').all().map(i => i.json);
const resp = $input.all().map(i => i.json);
const ops = [], hoy = ahora.toFormat('yyyy-MM-dd');
let usdcop = 0, usdFx = 0; const precio = {};
pedidos.forEach((p, i) => {
  const r = resp[i] || {};
  if (p.fuente === 'coingecko' && r.bitcoin) {
    if (r.bitcoin.usd && r.bitcoin.cop) usdcop = r.bitcoin.cop / r.bitcoin.usd;
    for (const [s, id] of Object.entries(p.mapa)) if (r[id] && r[id].usd) precio[s] = r[id].usd;
  }
  if (p.fuente === 'fx' && r.rates && r.rates.COP) usdFx = r.rates.COP;   // tasa de mercado, como la de Google
  if (p.fuente === 'stooq') { const l = String(r.data || '').trim().split('\n'); const v = (l[1] || '').split(','); const c = parseFloat(v[4]); if (c > 0) precio[p.activo] = c; }
});
if (usdFx) usdcop = usdFx;               // el dólar oficial manda; el de CoinGecko queda de respaldo
if (usdcop) precio.COPW = 1 / usdcop;   // COPW es una stablecoin en pesos
for (const a of (T['Activos'] || []).filter(a => a.Activo)) {
  const s = String(a.Activo).toUpperCase();
  if (precio[s]) ops.push({ tabla: 'Activos', tipo: 'update', row: a.row_number, cambios: { 'Precio manual USD': precio[s], 'Fecha precio manual': hoy } });
}
const fila = (T['Parámetros'] || []).find(r => r.Clave === 'usdcop_manual');
if (usdcop && fila) ops.push({ tabla: 'Parámetros', tipo: 'update', row: fila.row_number, cambios: { Valor: Math.round(usdcop * 100) / 100 } });
// Punto de partida: saldos iniciales sin costo → costo = valor de hoy
const dolar = usdcop || num(fila && fila.Valor) || 4000;
for (const o of (T['Operaciones inversión'] || []).filter(o => o['Tipo operación'] === 'Saldo inicial' && !num(o['Total COP']))) {
  const pu = precio[String(o.Activo).toUpperCase()] || num(o['Precio unitario USD']);
  const usd = num(o.Cantidad) * pu;
  ops.push({ tabla: 'Operaciones inversión', tipo: 'update', row: o.row_number, cambios: { 'Precio unitario USD': pu, 'Total USD': Math.round(usd * 100) / 100, 'Total COP': Math.round(usd * dolar), 'Estado revisión': 'OK', Notas: `Costo = valor del ${hoy} (punto de partida)` } });
}
return [{ json: { ops, precios: precio, usdcop } }];

const tz = 'America/Bogota';
const ahora = DateTime.now().setZone(tz);
const sello = ahora.toFormat('yyMMddHHmmss') + '-' + $execution.id;   // único aunque lleguen varias fotos en el mismo segundo
// Montos: acepta 25000, "25.000", "$ 25.000,50", "(3.797.362)"
const num = v => {
  if (typeof v === 'number') return v;
  let s = String(v ?? '').trim();
  if (!s || s === '-') return 0;
  const neg = /^\(.*\)$/.test(s) || s.startsWith('-');
  s = s.replace(/[^\d,.]/g, '');
  if (s.includes(',')) s = s.replace(/\./g, '').replace(',', '.');
  else if ((s.match(/\./g) || []).length > 1 || /\.\d{3}$/.test(s)) s = s.replace(/\./g, '');
  const n = parseFloat(s);
  return isNaN(n) ? 0 : (neg ? -n : n);
};
// Fechas: acepta 2026-09-29, 29/09/2026, con hora, o número de serie de Sheets
const fecha = v => {
  if (typeof v === 'number') return DateTime.fromISO('1899-12-30', { zone: tz }).plus({ days: Math.floor(v) });
  const s = String(v || '').trim();
  for (const f of ['yyyy-MM-dd', 'd/M/yyyy', 'd/M/yy', 'yyyy-MM-dd H:mm', 'yyyy-MM-dd H:mm:ss', 'd/M/yyyy H:mm', 'd/M/yyyy H:mm:ss']) {
    const d = DateTime.fromFormat(s, f, { zone: tz });
    if (d.isValid) return d;
  }
  return DateTime.fromISO(s, { zone: tz });
};
const pesos = n => (n < 0 ? '-$' : '$') + String(Math.abs(Math.round(n))).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

const T = $('Tablas').first().json;
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const movs = (T['Movimientos'] || []).filter(r => r.ID).map(r => ({ ...r, _fecha: fecha(r.Fecha), _monto: num(r.Monto) }));
const ENTRA = ['Ingreso', 'Préstamo recibido', 'Abono recibido', 'Cobro cuota', 'Ajuste', 'Venta reventa'];
const SALE = ['Gasto', 'Préstamo dado', 'Abono pagado', 'Transferencia', 'Pago tarjeta', 'Compra reventa'];
const DEST = ['Transferencia', 'Pago tarjeta'];
const cuentas = (T['Cuentas'] || []).filter(c => c.ID).map(c => {
  const ancla = fecha(c['Fecha saldo inicial']);
  const desde = ancla.isValid ? ancla.startOf('day') : DateTime.fromISO('1900-01-01');
  const mv = movs.filter(r => r._fecha.isValid && r._fecha >= desde);
  const sum = (campo, tipos) => mv.filter(r => String(r[campo]) === String(c.ID) && tipos.includes(r.Tipo)).reduce((s, r) => s + r._monto, 0);
  const ent = sum('Cuenta', ENTRA), sal = sum('Cuenta', SALE), dst = sum('Cuenta destino', DEST);
  const si = num(c['Saldo inicial']), tasa = num(c['Tasa EA']);
  let saldo;
  if (c.Tipo === 'Inversión') saldo = null;
  else if (c.Tipo === 'Tarjeta de crédito') saldo = si - ent + sal - dst;
  else if (c.Tipo === 'CDT') { const fin = fecha(c['Fecha vencimiento']), hasta = fin.isValid && fin < ahora ? fin : ahora;
    saldo = si * Math.pow(1 + tasa, Math.max(0, hasta.diff(desde, 'days').days) / 365) + ent - sal + dst; }
  else saldo = si + ent - sal + dst;
  return { ID: c.ID, Nombre: c.Nombre, Entidad: c.Entidad, Tipo: c.Tipo, Padre: c['Cuenta padre'] || '', Alias: String(c.Alias || ''),
    Activa: String(c.Activa || 'Sí') !== 'No', cobra4x1000: String(c['Cobra 4x1000']) === 'Sí', Cupo: num(c.Cupo), tasa,
    corte: num(c['Día de corte']), pago: num(c['Día de pago']), saldo, ancla: desde.toFormat('yyyy-MM-dd'), vence: c['Fecha vencimiento'] || '', row_number: c.row_number };
});
const cta = id => cuentas.find(c => c.ID === id) || {};
const nombreDe = id => cta(id).Nombre || id;
// Tarjetas: próximo pago, mínimo (cuotas que vencen hasta esa fecha) y total (toda la deuda)
const ctasT = (T['Cuotas tarjeta'] || []).filter(r => r.ID);
const tarjetas = cuentas.filter(c => c.Tipo === 'Tarjeta de crédito' && c.Activa).map(c => {
  const dia = c.pago || 10;
  let prox = ahora.set({ day: Math.min(dia, ahora.daysInMonth) }).startOf('day');
  if (prox < ahora.startOf('day')) { const m = ahora.plus({ months: 1 }); prox = m.set({ day: Math.min(dia, m.daysInMonth) }).startOf('day'); }
  const pend = ctasT.filter(r => r.Cuenta === c.ID && !['Pagada', 'Anulada'].includes(r.Estado));
  const minimo = pend.filter(r => fecha(r['Fecha de pago']) <= prox.endOf('day')).reduce((s, r) => s + num(r['Valor cuota']), 0);
  return { ID: c.ID, Nombre: c.Nombre, deuda: c.saldo, cupo: c.Cupo, prox: prox.toFormat('yyyy-MM-dd'), minimo, total: c.saldo };
});
// Personas y deudas: informal (préstamos dados sin préstamo formal − abonos) + cuotas pendientes de préstamos
const personas = (T['Personas'] || []).filter(p => p.Nombre);
const prestamos = (T['Préstamos'] || []).filter(p => p.ID);
const cuotasP = (T['Cuotas préstamo'] || []).filter(q => q['ID préstamo']);
const nombresPersona = [...new Set([...personas.map(p => p.Nombre), ...movs.map(r => r.Persona).filter(Boolean), ...prestamos.map(p => p.Persona)])];
const deudas = nombresPersona.map(nombre => {
  const deP = movs.filter(r => norm(r.Persona) === norm(nombre));
  const informal = deP.filter(r => r.Tipo === 'Préstamo dado' && !String(r.Referencia || '').startsWith('PR-')).reduce((s, r) => s + r._monto, 0)
    - deP.filter(r => r.Tipo === 'Abono recibido').reduce((s, r) => s + r._monto, 0);
  const cuotas = cuotasP.filter(q => norm(q.Persona) === norm(nombre) && !['Pagada', 'Anulada'].includes(q.Estado)).reduce((s, q) => s + num(q['Valor cuota']) - num(q['Valor recibido']), 0);
  const yoDebo = deP.filter(r => r.Tipo === 'Préstamo recibido').reduce((s, r) => s + r._monto, 0) - deP.filter(r => r.Tipo === 'Abono pagado').reduce((s, r) => s + r._monto, 0);
  const p = personas.find(x => norm(x.Nombre) === norm(nombre)) || {};
  return { nombre, alias: String(p.Alias || ''), relacion: p['Relación'] || '', informal, cuotas, total: informal + cuotas, yoDebo, row_number: p.row_number || null };
});
// Inversiones: cantidad, costo (promedio), valor actual y ganancia por activo
const Pm = k => ((T['Parámetros'] || []).find(r => r.Clave === k) || {}).Valor;
const usdcop = num(Pm('usdcop_manual')) || 4000;
const activos = (T['Activos'] || []).filter(a => a.Activo).map(a => ({ simbolo: String(a.Activo), nombre: a.Nombre || a.Activo, tipo: a['Tipo activo'] || 'Cripto', cuenta: a.Cuenta || '',
  precio: num(a['Precio manual USD']), fechaPrecio: a['Fecha precio manual'] || '', vigente: String(a['Activo vigente'] || 'Sí') !== 'No', notas: String(a.Notas || ''), row_number: a.row_number }));
const opsInv = (T['Operaciones inversión'] || []).filter(o => o.ID);
const portafolio = activos.map(a => {
  const os = opsInv.filter(o => String(o.Activo).toUpperCase() === a.simbolo.toUpperCase()).sort((x, y) => fecha(x.Fecha) - fecha(y.Fecha));
  let cantidad = 0, costo = 0, realizado = 0;
  for (const o of os) {
    const q = num(o.Cantidad), t = o['Tipo operación'], tcop = num(o['Total COP']);
    if (t === 'Saldo inicial' || t === 'Compra') { cantidad += q; costo += tcop || num(o['Total USD']) * usdcop; }
    else if (t === 'Venta') { const cu = cantidad ? costo / cantidad : 0; realizado += tcop - cu * q; costo -= cu * q; cantidad -= q; }
    else if (t === 'Ajuste' || t === 'Recompensa') cantidad += q;
  }
  const valor = cantidad * a.precio * usdcop;
  return { ...a, cantidad, costo, valor, ganancia: valor - costo, realizado };
});
const valorInversion = id => portafolio.filter(p => p.cuenta === id).reduce((s, p) => s + p.valor, 0);
// Reventas: inventario y ganancia
const reventas = (T['Reventas'] || []).filter(r => r.ID).map(r => {
  const c = num(r.Cantidad), v = num(r['Cantidad vendida']), u = num(r['Cantidad uso propio']), costo = num(r['Costo total']), unit = c ? costo / c : 0;
  return { ID: r.ID, articulo: r['Artículo'], cantidad: c, vendidas: v, uso: u, quedan: c - v - u, costo, unit, vendido: num(r['Total vendido']),
    ganancia: num(r['Total vendido']) - unit * v, estado: r.Estado, fecha: r['Fecha compra'], row_number: r.row_number };
});
// Presupuestos, metas y fondo de emergencia
const mesAct = ahora.toFormat('yyyy-MM');
const mesDe = v => {
  if (v === '' || v === null || v === undefined) return '';
  if (typeof v === 'number') return fecha(v).toFormat('yyyy-MM');
  const s = String(v).trim(); const m = s.match(/^(\d{4})-(\d{1,2})/); if (m) return `${m[1]}-${m[2].padStart(2, '0')}`;
  const f = fecha(s); if (f.isValid) return f.toFormat('yyyy-MM');
  const m2 = s.match(/(\d{1,2})\/(\d{4})$/); return m2 ? `${m2[2]}-${m2[1].padStart(2, '0')}` : '';
};
const presupuestos = (T['Presupuestos'] || []).filter(p => p['Categoría']).map(p => ({ mes: mesDe(p.Mes), categoria: p['Categoría'], monto: num(p.Monto), row_number: p.row_number }));
const gastoCat = mes => { const o = {}; for (const r of movs) if (r.Tipo === 'Gasto' && r._fecha.isValid && r._fecha.toFormat('yyyy-MM') === mes) { const c = r['Categoría'] || 'Sin categoría'; o[c] = (o[c] || 0) + r._monto; } return o; };
const estadoPres = mes => { const g = gastoCat(mes); return presupuestos.filter(p => p.mes === mes).map(p => ({ ...p, gastado: g[p.categoria] || 0, pct: p.monto ? (g[p.categoria] || 0) / p.monto : 0 })); };
const gastoMes = mes => Object.values(gastoCat(mes)).reduce((s, v) => s + v, 0);
const mesesAtras = [1, 2, 3].map(i => ahora.minus({ months: i }).toFormat('yyyy-MM')).filter(m => gastoMes(m) > 0);
const gastoPromedio = mesesAtras.length ? mesesAtras.reduce((s, m) => s + gastoMes(m), 0) / mesesAtras.length : gastoMes(mesAct);
const disponible = cuentas.filter(c => c.Activa && !['Tarjeta de crédito', 'Inversión', 'CDT'].includes(c.Tipo) && c.saldo != null).reduce((s, c) => s + c.saldo, 0);
const metas = (T['Metas'] || []).filter(m => m.ID).map(m => ({ ID: m.ID, nombre: m.Nombre, cuenta: m.Cuenta, objetivo: num(m['Monto objetivo']), fin: m['Fecha objetivo'], estado: m.Estado || 'Activa', row_number: m.row_number }));
const avanceMeta = m => { const c = cuentas.find(x => x.ID === m.cuenta) || {}; const tiene = Math.max(0, c.saldo || 0); const f = fecha(m.fin);
  const mesesF = f.isValid ? Math.max(1, Math.ceil(f.diff(ahora, 'months').months)) : null;
  return { ...m, tiene, pct: m.objetivo ? tiene / m.objetivo : 0, falta: Math.max(0, m.objetivo - tiene), porMes: mesesF ? Math.max(0, m.objetivo - tiene) / mesesF : null, cuentaNombre: c.Nombre || m.cuenta }; };
const resumenPrestamos = prestamos.map(p => {
  const qs = cuotasP.filter(q => q['ID préstamo'] === p.ID).sort((a, b) => num(a['Nº']) - num(b['Nº']));
  const pend = qs.filter(q => !['Pagada', 'Anulada'].includes(q.Estado));
  return { ID: p.ID, persona: p.Persona, monto: num(p['Monto prestado']), n: num(p['Nº cuotas']), valor: num(p['Valor cuota']), frecuencia: p.Frecuencia,
    cuenta_cobro: p['Cuenta de cobro habitual'] || '', pagadas: qs.length - pend.length, pendientes: pend.length,
    saldo: pend.reduce((s, q) => s + num(q['Valor cuota']) - num(q['Valor recibido']), 0),
    proxima: pend[0] ? { n: num(pend[0]['Nº']), fecha: pend[0].Fecha, valor: num(pend[0]['Valor cuota']) - num(pend[0]['Valor recibido']) } : null };
});

// Revisión diaria: cobros recurrentes, cuotas por cobrar, pago de tarjeta y (domingos) revisión de rendimientos
const d0 = ahora.startOf('day'), hoyTxt = d0.toFormat('yyyy-MM-dd'), creado = ahora.toFormat('yyyy-MM-dd HH:mm');
const P = k => ((T['Parámetros'] || []).find(r => r.Clave === k) || {}).Valor;
const ops = [], mensajes = [];
let k = 0;
const diaEs = f => f.setLocale('es').toFormat("cccc d 'de' LLLL");
// Si el servidor estuvo apagado, se revisan también los días que no corrió (máx. 7)
const ult = fecha(P('ultima_agenda'));
const diasRev = [];
for (let x = ult.isValid && ult < d0 ? DateTime.max(ult.plus({ days: 1 }).startOf('day'), d0.minus({ days: 7 })) : d0; x <= d0; x = x.plus({ days: 1 })) diasRev.push(x);
const filaU = (T['Parámetros'] || []).find(x => x.Clave === 'ultima_agenda');
if (filaU) ops.push({ tabla: 'Parámetros', tipo: 'update', row: filaU.row_number, cambios: { Valor: hoyTxt } });
else ops.push({ tabla: 'Parámetros', tipo: 'append', fila: { Clave: 'ultima_agenda', Valor: hoyTxt, 'Descripción': 'Último día que revisó la Agenda (para recuperar días perdidos)' } });
// Para no preguntar dos veces por el mismo cobro (por ejemplo, si se ejecuta a mano)
const yaPreguntado = (recId, cobro, anual) => (T['Por confirmar'] || []).some(x => x['ID relacionado'] === recId && fecha(x.Creado).isValid && fecha(x.Creado).hasSame(cobro, anual ? 'year' : 'month') && fecha(x.Creado) >= cobro.minus({ days: 1 }));

// 1) Recurrentes (suscripciones y gastos fijos)
