// Resumen semanal (domingo) y mensual (día 1): mensaje, gráficas, Historial, copia del presupuesto y limpieza
const manual = ['manual', 'test'].includes($execution.mode);   // al ejecutarlo a mano sale el resumen semanal (para probar)
const semanal = manual || (ahora.weekday === 7 && ahora.hour >= 18), mensual = ahora.day === 1 && ahora.hour < 12;
const ops = [], borrar = [], graficas = []; let texto = '';
const P = k => ((T['Parámetros'] || []).find(r => r.Clave === k) || {}).Valor;
const inicioSem = ahora.startOf('day').minus({ days: 6 }), finSem = ahora.endOf('day');
const enRango = (r, a, b) => r._fecha.isValid && r._fecha >= a && r._fecha <= b;
const gastos = (a, b) => movs.filter(r => r.Tipo === 'Gasto' && enRango(r, a, b));
const porCat = lista => { const o = {}; for (const r of lista) { const c = r['Categoría'] || 'Sin categoría'; o[c] = (o[c] || 0) + r._monto; } return Object.entries(o).sort((x, y) => y[1] - x[1]); };
const inv = portafolio.reduce((s, p) => s + p.valor, 0);
const deudaT = tarjetas.reduce((s, t) => s + (t.deuda || 0), 0);
const futuras = ctasT.filter(q => !['Pagada', 'Anulada'].includes(q.Estado)).reduce((s, q) => s + num(q['Valor cuota']), 0);
const meDeben = deudas.reduce((s, d) => s + Math.max(0, d.total), 0), yoDebo = deudas.reduce((s, d) => s + Math.max(0, d.yoDebo), 0);
const patrimonio = disponible + inv + meDeben - deudaT - yoDebo;
const colores = ['#6C5CE7', '#00B894', '#FDCB6E', '#E17055', '#0984E3', '#E84393', '#00CEC9', '#B2BEC3'];
// Gráficas (Chart.js 4 en QuickChart): se arman como texto para poder incluir funciones de formato
const F = {
  pesos: "function(v){v=Number(v);var a=Math.abs(v);var s=a>=1e6?(a/1e6).toFixed(1).replace('.',',')+' M':a>=1e3?Math.round(a/1e3)+' mil':Math.round(a);return (v<0?'-$':'$')+s}",
  pctDona: "function(v,ctx){var t=ctx.dataset.data.reduce(function(a,b){return a+b},0);var p=Math.round(v*100/t);return p>=6?p+'%':''}",
  pctBarra: "function(v,ctx){if(ctx.datasetIndex!==1)return '';var p=ctx.chart.data.datasets[0].data[ctx.dataIndex];return p?Math.round(v*100/p)+'%':'sin presupuesto'}",
  ultimo: "function(ctx){return ctx.dataIndex===ctx.dataset.data.length-1}"
};
const chartJs = obj => JSON.stringify(obj).replace(/"__(pesos|pctDona|pctBarra|ultimo)__"/g, (_, k) => F[k]);
const corto = v => { const a = Math.abs(v); return (v < 0 ? '-$' : '$') + (a >= 1e6 ? (a / 1e6).toFixed(1).replace('.', ',') + ' M' : a >= 1e3 ? Math.round(a / 1e3) + ' mil' : Math.round(a)); };
const titulo = (t, sub) => ({ display: true, text: t, color: '#2D3436', font: { size: 24, weight: 'bold' }, padding: { top: 6, bottom: sub ? 2 : 18 } });
const subtitulo = t => ({ display: !!t, text: t, color: '#636E72', font: { size: 16 }, padding: { bottom: 18 } });
const leyenda = pos => ({ position: pos, labels: { color: '#2D3436', font: { size: 15 }, boxWidth: 16, boxHeight: 16, usePointStyle: true, pointStyle: 'rectRounded', padding: 16 } });

if (semanal) {
  const gs = gastos(inicioSem, finSem), gsAnt = gastos(inicioSem.minus({ days: 7 }), inicioSem.minus({ milliseconds: 1 }));
  const tot = gs.reduce((s, r) => s + r._monto, 0), totAnt = gsAnt.reduce((s, r) => s + r._monto, 0);
  const ing = movs.filter(r => ['Ingreso', 'Venta reventa', 'Cobro cuota'].includes(r.Tipo) && enRango(r, inicioSem, finSem)).reduce((s, r) => s + r._monto, 0);
  const rend = movs.filter(r => r.Tipo === 'Ingreso' && r['Categoría'] === 'Rendimientos' && enRango(r, inicioSem, finSem)).reduce((s, r) => s + r._monto, 0);
  const cats = porCat(gs), top = gs.slice().sort((x, y) => y._monto - x._monto).slice(0, 3);
  const ep = estadoPres(mesAct);
  const hoyH = ahora.toFormat('yyyy-MM-dd');
  const histPrev = (T['Historial'] || []).filter(h => h.Fecha && fecha(h.Fecha).isValid && fecha(h.Fecha).toFormat('yyyy-MM-dd') < hoyH);
  const hist = histPrev.slice(-1)[0];
  const cambioPat = hist ? patrimonio - num(hist['Patrimonio neto']) : null;
  texto = `📅 Tu semana (${inicioSem.setLocale('es').toFormat('d LLL')} – ${ahora.setLocale('es').toFormat('d LLL')})\n\n` +
    `💸 Gastaste ${pesos(tot)}` + (totAnt ? ` (${tot > totAnt ? '▲' : '▼'} ${Math.abs(Math.round((tot - totAnt) * 100 / totAnt))}% vs. la semana pasada)` : '') + '\n' +
    (cats.length ? cats.slice(0, 5).map(([c, v]) => `• ${c}: ${pesos(v)}`).join('\n') + '\n' : '') +
    (top.length ? `Lo más grande: ${top.map(r => `${r.Detalle || r.Comercio} (${pesos(r._monto)})`).join(', ')}\n` : '') +
    (ing ? `💰 Entraron ${pesos(ing)}${rend ? ` (${pesos(rend)} de rendimientos)` : ''}\n` : '') +
    (ep.length ? `\n📊 Presupuesto del mes: ${ep.filter(p => p.pct >= 1).length ? '🚨 ' + ep.filter(p => p.pct >= 1).map(p => p.categoria).join(', ') + ' pasado(s). ' : ''}${ep.filter(p => p.pct >= 0.8 && p.pct < 1).length ? '⚠️ Cerca: ' + ep.filter(p => p.pct >= 0.8 && p.pct < 1).map(p => `${p.categoria} ${Math.round(p.pct * 100)}%`).join(', ') + '. ' : ''}Total ${pesos(ep.reduce((s, p) => s + p.gastado, 0))} de ${pesos(ep.reduce((s, p) => s + p.monto, 0))}.\n` : '') +
    `\n🏦 Disponible ${pesos(disponible)} · 📈 Inversiones ${pesos(inv)}\n💳 Tarjeta ${pesos(deudaT)} · 🤝 Te deben ${pesos(meDeben)}\n` +
    `🧮 Patrimonio neto ${pesos(patrimonio)}` + (cambioPat !== null ? ` (${cambioPat >= 0 ? '+' : '-'}${pesos(Math.abs(cambioPat))} en la semana)` : '');
  // Foto semanal para el historial
  const filaH = { Fecha: hoyH, 'Efectivo y cuentas': Math.round(disponible), 'Inversiones COP': Math.round(inv), 'Deuda tarjetas': Math.round(deudaT),
    'Cuotas tarjeta futuras': Math.round(futuras), 'Me deben': Math.round(meDeben), 'Yo debo': Math.round(yoDebo), 'Patrimonio neto': Math.round(patrimonio),
    'Gasto de la semana': Math.round(tot), 'Gasto del mes': Math.round(gastoMes(mesAct)), 'Rendimientos de la semana': Math.round(rend) };
  // Una sola foto por día: si ya existe la de hoy (por ejecutarlo varias veces), se actualiza
  const yaHoy = (T['Historial'] || []).find(h => h.Fecha && fecha(h.Fecha).isValid && fecha(h.Fecha).toFormat('yyyy-MM-dd') === hoyH);
  if (yaHoy) ops.push({ tabla: 'Historial', tipo: 'update', row: yaHoy.row_number, cambios: filaH }); else ops.push({ tabla: 'Historial', tipo: 'append', fila: filaH });
  // Gráficas
  if (cats.length) {
    const top = cats.slice(0, 7), resto = cats.slice(7).reduce((s, c) => s + c[1], 0);
    if (resto) top.push(['Otras', resto]);
    graficas.push({ titulo: 'En qué gastaste esta semana', ancho: 1000, alto: 560, chart: chartJs({ type: 'doughnut',
      data: { labels: top.map(c => `${c[0]}  ${corto(c[1])}`), datasets: [{ data: top.map(c => Math.round(c[1])), backgroundColor: colores, borderColor: '#FFFFFF', borderWidth: 4, hoverOffset: 0 }] },
      options: { cutout: '58%', layout: { padding: 16 }, plugins: { title: titulo('¿En qué gastaste esta semana?', true), subtitle: subtitulo(`Total: ${pesos(tot)}`), legend: leyenda('right'),
        datalabels: { color: '#FFFFFF', font: { size: 16, weight: 'bold' }, formatter: '__pctDona__' } } } }) });
  }
  if (ep.length) {
    const orden = ep.slice().sort((x, y) => y.pct - x.pct);
    graficas.push({ titulo: 'Presupuesto del mes', ancho: 1000, alto: Math.max(360, 150 + orden.length * 70), chart: chartJs({ type: 'bar',
      data: { labels: orden.map(p => `${p.categoria} · ${Math.round(p.pct * 100)}%`), datasets: [
        { label: 'Presupuesto', data: orden.map(p => Math.round(p.monto)), backgroundColor: '#E9EDF0', borderRadius: 8, borderSkipped: false, barPercentage: 0.95, categoryPercentage: 0.75 },
        { label: 'Gastado', data: orden.map(p => Math.round(p.gastado)), backgroundColor: orden.map(p => p.pct >= 1 ? '#E74C3C' : p.pct >= 0.8 ? '#F5B041' : '#27AE60'), borderRadius: 8, borderSkipped: false, barPercentage: 0.95, categoryPercentage: 0.75 }] },
      options: { indexAxis: 'y', layout: { padding: { right: 30, left: 8 } },
        plugins: { title: titulo(`Presupuesto de ${ahora.setLocale('es').toFormat('LLLL')}`, true), subtitle: subtitulo(`Llevas ${pesos(orden.reduce((s, p) => s + p.gastado, 0))} de ${pesos(orden.reduce((s, p) => s + p.monto, 0))}`), legend: leyenda('bottom'),
          datalabels: { display: false } },
        scales: { x: { beginAtZero: true, grid: { color: '#F0F0F0' }, border: { display: false }, ticks: { color: '#636E72', font: { size: 13 }, callback: '__pesos__' } },
          y: { grid: { display: false }, border: { display: false }, ticks: { color: '#2D3436', font: { size: 16, weight: 'bold' } } } } } }) });
  }
  const serie = [...histPrev.slice(-11).map(h => ({ f: fecha(h.Fecha), pat: num(h['Patrimonio neto']), deuda: num(h['Deuda tarjetas']) })), { f: ahora, pat: patrimonio, deuda: deudaT }];
  if (serie.length >= 2) graficas.push({ titulo: 'Evolución', ancho: 1000, alto: 560, chart: chartJs({ type: 'line',
    data: { labels: serie.map(x => x.f.setLocale('es').toFormat('d LLL')), datasets: [
      { label: 'Patrimonio neto', data: serie.map(x => Math.round(x.pat)), borderColor: '#6C5CE7', backgroundColor: 'rgba(108,92,231,0.12)', fill: true, tension: 0.35, borderWidth: 4, pointRadius: 5, pointBackgroundColor: '#6C5CE7' },
      { label: 'Deuda de la tarjeta', data: serie.map(x => Math.round(x.deuda)), borderColor: '#E74C3C', borderDash: [8, 6], fill: false, tension: 0.35, borderWidth: 3, pointRadius: 4, pointBackgroundColor: '#E74C3C' }] },
    options: { layout: { padding: { right: 40, top: 10 } }, plugins: { title: titulo('Patrimonio y deuda', true), subtitle: subtitulo('Semana a semana'), legend: leyenda('bottom'),
        datalabels: { display: '__ultimo__', align: 'top', offset: 8, color: '#2D3436', font: { size: 15, weight: 'bold' }, formatter: '__pesos__' } },
      scales: { x: { grid: { display: false }, ticks: { color: '#636E72', font: { size: 14 } } }, y: { grid: { color: '#F0F0F0' }, border: { display: false }, ticks: { color: '#636E72', font: { size: 13 }, callback: '__pesos__' } } } } }) });
}

if (mensual) {
  const mAnt = ahora.minus({ months: 1 }), kAnt = mAnt.toFormat('yyyy-MM');
  const gm = gastos(mAnt.startOf('month'), mAnt.endOf('month')), tot = gm.reduce((s, r) => s + r._monto, 0);
  const ing = movs.filter(r => ['Ingreso', 'Venta reventa'].includes(r.Tipo) && enRango(r, mAnt.startOf('month'), mAnt.endOf('month'))).reduce((s, r) => s + r._monto, 0);
  const ep = estadoPres(kAnt);
  texto += (texto ? '\n\n' : '') + `🗓️ Resumen de ${mAnt.setLocale('es').toFormat('LLLL')}\n💸 Gastos: ${pesos(tot)} · 💰 Ingresos: ${pesos(ing)}\n` +
    porCat(gm).slice(0, 6).map(([c, v]) => { const p = ep.find(x => x.categoria === c); return `• ${c}: ${pesos(v)}${p ? ` de ${pesos(p.monto)} ${v > p.monto ? '🚨' : '✅'}` : ''}`; }).join('\n');
  // Copia el presupuesto al mes nuevo si no existe
  const yaHay = presupuestos.some(p => p.mes === mesAct), anterior = presupuestos.filter(p => p.mes === kAnt);
  if (!yaHay && anterior.length) {
    for (const p of anterior) ops.push({ tabla: 'Presupuestos', tipo: 'append', fila: { Mes: mesAct, 'Categoría': p.categoria, Monto: p.monto, Notas: 'Copiado del mes anterior', Creado: ahora.toFormat('yyyy-MM-dd HH:mm'), Modificado: ahora.toFormat('yyyy-MM-dd HH:mm') } });
    texto += `\n\n📋 Copié tu presupuesto de ${mAnt.setLocale('es').toFormat('LLLL')} a ${ahora.setLocale('es').toFormat('LLLL')} (${pesos(anterior.reduce((s, p) => s + p.monto, 0))}). Si quieres cambiar algo, dime por ejemplo "pon 350 mil para comida".`;
  }
}

// Limpieza: Log Bot de más de 90 días (las filas más viejas están arriba) y confirmaciones cerradas de más de 30 días
if (semanal) {
  const meta = ($('Metadatos').first().json.sheets || []).map(x => x.properties);
  const gid = t => (meta.find(x => x.title === t) || {}).sheetId;
  const log = T['Log Bot'] || []; let k = 0;
  while (k < log.length && fecha(log[k].FechaHora).isValid && fecha(log[k].FechaHora) < ahora.minus({ days: 90 }) && log[k].row_number === k + 2) k++;
  if (k && gid('Log Bot') !== undefined) borrar.push({ deleteDimension: { range: { sheetId: gid('Log Bot'), dimension: 'ROWS', startIndex: 1, endIndex: 1 + k } } });
  const viejas = (T['Por confirmar'] || []).filter(x => x.Estado !== 'Pendiente' && fecha(x.Creado).isValid && fecha(x.Creado) < ahora.minus({ days: 30 })).map(x => x.row_number).sort((a, b) => b - a);
  if (gid('Por confirmar') !== undefined) for (const rn of viejas) borrar.push({ deleteDimension: { range: { sheetId: gid('Por confirmar'), dimension: 'ROWS', startIndex: rn - 1, endIndex: rn } } });
  if (k || viejas.length) texto += `\n\n🧹 Limpieza: ${k} registros viejos del Log Bot y ${viejas.length} confirmaciones cerradas.`;
}
return [{ json: { ops, borrar, graficas, mensaje: texto || '', semanal } }];

// Deja solo los 8 respaldos más recientes
const archivos = $input.all().map(i => i.json).filter(f => f.id && /^Respaldo FinanzasWilliam/.test(f.name || ''));
archivos.sort((a, b) => String(b.name).localeCompare(String(a.name)));
const viejos = archivos.slice(8);
return viejos.length ? viejos.map(f => ({ json: { id: f.id, name: f.name } })) : [{ json: { vacio: true } }];

// Convierte las filas en pedidos a la API de Google Sheets: un "append" por pestaña y un "batchUpdate" para las ediciones
const T = $('Tablas').first().json;
const ops = $('Reporte').first().json.ops || [];
const H = T._h || {};
const base = 'https://sheets.googleapis.com/v4/spreadsheets/1n97Po-FMwXt0XHwrSp4LLjCsyUMpKBdcUksFxkxJ8GM';
const col = i => { let s = ''; i++; while (i > 0) { const m = (i - 1) % 26; s = String.fromCharCode(65 + m) + s; i = Math.floor((i - 1) / 26); } return s; };
const COL_FECHA = /^(Fecha|Creado|Modificado|Expira|Actualizado|Hora|Mes)/i;
const limpio = (v, col) => (typeof v === 'string' && (/^[=+@]/.test(v) || (!COL_FECHA.test(col || '') && /^\d{1,2}[\/:-]\d{1,2}([\/-]\d{2,4})?$/.test(v.trim())))) ? "'" + v : (v === undefined || v === null ? '' : v);
const items = [], porTabla = {};
for (const o of ops.filter(o => o.tipo === 'append' && (H[o.tabla] || []).length)) (porTabla[o.tabla] = porTabla[o.tabla] || []).push(H[o.tabla].map(h => limpio(o.fila[h], h)));
for (const [t, filas] of Object.entries(porTabla))
  items.push({ json: { url: `${base}/values/${encodeURIComponent("'" + t + "'!A1")}:append?valueInputOption=USER_ENTERED&insertDataOption=INSERT_ROWS`, body: { values: filas } } });
const data = [];
for (const o of ops.filter(o => o.tipo === 'update'))
  for (const [c, v] of Object.entries(o.cambios)) { const i = (H[o.tabla] || []).indexOf(c); if (i >= 0) data.push({ range: `'${o.tabla}'!${col(i)}${o.row}`, values: [[limpio(v, c)]] }); }
if (data.length) items.push({ json: { url: `${base}/values:batchUpdate`, body: { valueInputOption: 'USER_ENTERED', data } } });
const borrar = $('Reporte').first().json.borrar || [];
if (borrar.length) items.push({ json: { url: `${base}:batchUpdate`, body: { requests: borrar } } });
return items.length ? items : [{ json: { vacio: true } }];
